from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype
from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.ResetCuFactory import ResetCuFactory


class LteRatReset(OperationPrototype):
    def __init__(self, bts):
        super(LteRatReset, self).__init__(bts)
        self.operation_details = {
            "Timeout": 120,
            "Operation": "LTE Rat Reset",
            "Start Point": "First LTE cell down",
            "End point": "Last LTE cell up",
            "Requirement": "OM_GEN_SFS_PERF_CAP.12896",
        }

    def get_kpi(self):  # noqa: C901
        """
        Gets kpi for LTE rat reset operation.
        :return: dictionary with timeout, requirement and operation description for LTE rat reset
        :rtype: dict
        """
        if any(
            (
                all(
                    [
                        self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIA", "ABIO", "ABIL"]),
                        self.bts.number_of_smods <= 2,
                        self.bts.number_of_bbmods <= 6,
                        self.bts.number_of_lte_cells <= 8,
                        self.bts.number_of_nr_cells <= 4,
                        self.bts.cell_technologies == "MIX",
                        self.bts.is_multi_rat,
                        self.bts.number_of_super_cells == 2,
                        self.bts.setup_mode == "NSA",
                        self.bts.rf_sharing,
                        "ASIRMOD" in self.bts.rmod_hw_types,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 480 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19521"

        elif any(
            (
                all(
                    [
                        "ASIL" in self.bts.smod_hw_types,
                        "APHH" in self.bts.smod_hw_types,
                        "ABIO" in self.bts.bbmod_hw_types,
                        self.bts.number_of_smods <= 2,
                        self.bts.number_of_bbmods <= 6,
                        self.bts.number_of_lte_cells <= 48,
                        self.bts.number_of_nr_cells <= 60,
                        self.bts.cell_technologies == "MIX",
                        self.bts.is_multi_rat,
                        self.bts.is_full_rack,
                        self.bts.setup_mode == "SA",
                        "APHG" in self.bts.rmod_hw_types,
                        "AWHGEQK" in self.bts.rmod_hw_types,
                        "AWHENHD" in self.bts.rmod_hw_types,
                        "AWHGEQH" in self.bts.rmod_hw_types,
                        "AWHHIQB" in self.bts.rmod_hw_types,
                        "ASIRMOD" in self.bts.rmod_hw_types,
                        self.bts.rf_sharing,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 720 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.28754"

        elif any(
            (
                all(
                    [
                        "ASIL" in self.bts.smod_hw_types,
                        "ABIO" in self.bts.bbmod_hw_types,
                        self.bts.number_of_smods <= 2,
                        self.bts.number_of_bbmods <= 6,
                        self.bts.number_of_rmods <= 77,
                        self.bts.number_of_lte_cells <= 48,
                        self.bts.number_of_nr_cells <= 60,
                        self.bts.cell_technologies == "MIX",
                        self.bts.radio_protocol == "MIX",
                        self.bts.is_multi_rat,
                        self.bts.is_full_rack,
                        self.bts.setup_mode == "SA",
                        self.bts.rf_sharing,
                        "ASIRMOD" in self.bts.rmod_hw_types,
                        "APHG" in self.bts.rmod_hw_types,
                        "AWHGEQK" in self.bts.rmod_hw_types,
                        "AWHENHD" in self.bts.rmod_hw_types,
                        "AWHGEQH" in self.bts.rmod_hw_types,
                        "AWHHIQB" in self.bts.rmod_hw_types,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 504 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.28756"

        elif any(
            (
                all(
                    [
                        "ASIL" in self.bts.smod_hw_types,
                        "ABIO" in self.bts.bbmod_hw_types,
                        self.bts.number_of_smods <= 2,
                        self.bts.number_of_bbmods <= 6,
                        self.bts.number_of_lte_cells <= 48,
                        self.bts.number_of_nr_cells <= 60,
                        self.bts.cell_technologies == "MIX",
                        self.bts.is_multi_rat,
                        self.bts.setup_mode == "SA",
                        self.bts.rf_sharing,
                        "ASIRMOD" in self.bts.rmod_hw_types,
                        "APHG" in self.bts.rmod_hw_types,
                        "AWHGEQK" in self.bts.rmod_hw_types,
                        "AWHENHD" in self.bts.rmod_hw_types,
                        "AWHGEQH" in self.bts.rmod_hw_types,
                        "AWHHIQB" in self.bts.rmod_hw_types,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 504 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.25557"

        elif any(
            (
                all(
                    [
                        "ASIB" in self.bts.smod_hw_types,
                        "ABIA" in self.bts.bbmod_hw_types,
                        "ABIL" in self.bts.bbmod_hw_types,
                        "ABIO" in self.bts.bbmod_hw_types,
                        self.bts.number_of_smods <= 2,
                        self.bts.number_of_bbmods <= 6,
                        self.bts.number_of_lte_cells <= 8,
                        self.bts.number_of_nr_cells <= 10,
                        self.bts.cell_technologies == "MIX",
                        self.bts.is_multi_rat,
                        self.bts.setup_mode == "NSA",
                        self.bts.number_of_super_cells == 2,
                        self.bts.rf_sharing,
                        "ASIRMOD" in self.bts.rmod_hw_types,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 240 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26675"

        elif any(
            (
                all(
                    [
                        "ASOG" in self.bts.smod_hw_types,
                        "ABIO" in self.bts.bbmod_hw_types,
                        self.bts.number_of_smods == 1,
                        0 < self.bts.number_of_lte_cells <= 3,
                        self.bts.cell_technologies == "FDD",
                        self.bts.radio_protocol == "CPRI",
                        self.bts.setup_mode == "SA",
                        "AHEGB" in self.bts.rmod_hw_types or "AHEH" in self.bts.rmod_hw_types,
                        not self.bts.is_multi_rat,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 300
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26563"

        elif any(
            (
                all(
                    [
                        "ASOF" in self.bts.smod_hw_types,
                        self.bts.number_of_smods == 1,
                        self.bts.number_of_rmods <= 2,
                        self.bts.number_of_lte_cells <= 2,
                        self.bts.number_of_nr_cells <= 2,
                        self.bts.cell_technologies == "TDD",
                        self.bts.radio_protocol == "eCPRI",
                        self.bts.is_multi_rat,
                        self.bts.setup_mode == "SA",
                        not self.bts.rf_sharing,
                        "AWPNA" in self.bts.rmod_hw_types or "AWPNB" in self.bts.rmod_hw_types,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 120 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.29284"

        elif any(
            (
                all(
                    [
                        "ASOG" in self.bts.smod_hw_types,
                        self.bts.number_of_smods == 1,
                        self.bts.number_of_rmods <= 3,
                        0 < self.bts.number_of_lte_cells <= 3,
                        self.bts.cell_technologies == "FDD",
                        self.bts.radio_protocol == "CPRI",
                        not self.bts.is_multi_rat,
                        "AHEGB" in self.bts.rmod_hw_types or "AHEH" in self.bts.rmod_hw_types,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 300 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26563"

        else:
            if self.bts.is_full_rack:
                self.operation_details["Timeout"] += 60

            use_cu = self.restrictions.should_use_cu_reset_via_restrictions_OM_GEN_SFS_PERF_CAP_10515(rat='lte')
            if use_cu:
                cu_reset = ResetCuFactory()
                cu_reset.bts_setter(self.bts)
                cu_reset_kpi = cu_reset.get_kpi()
                self.operation_details["Timeout"] = cu_reset_kpi["Timeout"]
                self.operation_details["Requirement"] += \
                    " + " + cu_reset_kpi["Requirement"] + " via OM_GEN_SFS_PERF_CAP.10515"

            self.operation_details["Timeout"] += self.restrictions. \
                get_extra_time_from_restrictions_OM_GEN_SFS_PERF_CAP_10515(rat='lte')

        return self.operation_details
